import sys
from collections import defaultdict, deque

def bfs(start, color, graph, visited):
    queue = deque([start])
    while queue:
        node = queue.popleft()
        for neighbor, edge_color in graph[node]:
            if edge_color == color and not visited[neighbor]:
                visited[neighbor] = True
                queue.append(neighbor)

