def find_path(a, b, parent):
    path = []
    while a != b:
        path.append(a)
        a = parent[a]
    path.append(b)
    return path

def lca(u, v, parent, depth):
    if depth[u] < depth[v]:
        u, v = v, u
    while depth[u] > depth[v]:
        u = parent[u]
    while u != v:
        u = parent[u]
        v = parent[v]
    return u

def dfs(node, par, dep, graph, parent, depth):
    parent[node] = par
    depth[node] = dep
    for neighbor, _ in graph[node]:
        if neighbor != par:
            dfs(neighbor, node, dep + 1, graph, parent, depth)

